perl << 'EOF'
use LWP::UserAgent;
use JSON;

my @endpoints = (
    "http://localhost:3003/checkConnectivity?variant=2",
    "https://httpstat.us/200"
);

my $ua = LWP::UserAgent->new(timeout => 5);

foreach my $url (@endpoints) {
    print "\n" . ("="x60) . "\n";
    print "Checking: $url\n";
    print "="x60 . "\n";

    my $response = $ua->get($url);

    if ($response->is_success) {
        print "✓ Status Code: " . $response->code . "\n";
        print "Content-Type: " . ($response->content_type // 'Not specified') . "\n";
        print "Response Body:\n" . $response->content . "\n";
    } else {
        print "✗ HTTP Error " . $response->code . ": " . $response->message . "\n";
        print "Error Details: " . $response->content . "\n" if $response->content;
    }
}
EOF
